-- Generated by generate_update_sql.py
-- Filters: difficulty=MEDIUM | created_by=ee42009d-d83e-4c12-abd1-2d8fff809b18 | role=TEACHER
-- Fields updated: 1
-- Only the specified content_keys are changed; all other values remain untouched.

BEGIN;

WITH
-- M1 - Reading Paragraph: update 'passage' (30 lesson(s))
m1_passage_data AS (
    SELECT * FROM (VALUES
        ('Two Feelings at Once', 'Mia had been excited for weeks about the school talent show. But the morning of the show, she woke up with a knot in her stomach. She wanted to perform and she also wanted to stay home. She told her mom, who said, ''It''s okay to feel two things at the same time.'' Mia thought about that on the bus. She was nervous AND excited. She decided both feelings were allowed to be there. When it was her turn to go on stage, the nervous part was still there but so was the excited part. She sang her song, and at the end, when the audience clapped, the excited feeling grew bigger. The nervous feeling didn''t disappear but it had made room.'),
        ('The Borrowed Eraser', 'Leo borrowed an eraser from his classmate Yuna without asking because he thought she wasn''t using it. When Yuna looked for it later and couldn''t find it, she looked upset. Leo hadn''t meant to cause a problem. He remembered how bad it felt when something of his went missing. He walked over to Yuna and said quietly, ''I''m sorry that I took your eraser without asking. Here it is.'' Yuna looked surprised, then nodded and took it back. Leo felt relieved not because it had been easy, but because he had done the right thing even when it would''ve been simpler not to.'),
        ('Left Out on Purpose', 'At lunch, Sofia noticed that her friend group were playing without her. She wasn''t sure if it was an accident or if they had done it on purpose. She felt hurt and a little angry, but she also didn''t want to make a big scene. She decided to wait and see what happened. When Priya came over later she said ‘Oh I’m sorry, it wasn''t on purpose, we just started playing and forgot. I''m so sorry.'' Sofia felt at ease and learned that sometimes a misunderstanding just needs a little patience.'),
        ('The Group Vote', 'The class voted on a topic for their science project, and Marcus''s idea lost. He had worked hard on his pitch and felt certain the class would choose his topic. When the results came in, he wanted to argue that the vote was wrong. But he looked at the other students who had voted for the winning idea and saw that they were genuinely excited. He took a slow breath and joined the winning team''s planning session. He didn''t pretend to be thrilled right away but he made himself show up. By the end of the session, he actually had a few good ideas to add.'),
        ('The Apology That Was Hard', 'Camille had accidentally said something unkind about a classmate''s drawing during art. She saw the student''s face change and knew the words had landed differently than she meant. All afternoon she thought about it. Part of her wondered: does it matter whether you meant to? After school, she took a breath and walked up to the student and said, “I said something I shouldn''t have about your drawing. I''m sorry.” The student was quiet for a moment, nodded, and then said, ''Thanks.'' Camille had been nervous about that conversation. Walking home, she felt lighter and glad she had done it the right way.'),
        ('A New Partner', 'For the science lab, the teacher assigned partners, and Jasper was paired with a student named Cole who he didn''t know well. Jasper would have chosen his friend Darius. He felt a little disappointed not because Cole had done anything wrong, but just because Darius was more comfortable. Cole walked over with a notebook full of organized color-coded notes and they started working. Cole had a system for tracking their results that was better than anything Jasper had thought of. By the end of the class, they had the most complete data sheet in the room. Walking out, Jasper thought about how sometimes an unfamiliar new situation can turn out to be amazing.'),
        ('Two Sides of the Story', 'At recess, Zara saw her friend push another student and thought she knew exactly what had happened. She went to tell the teacher, certain of what she had seen. But the teacher asked Zara to wait while she talked to both students. Zara listened from nearby. The student who had been pushed had actually grabbed Zara''s friend''s arm first, something Zara hadn''t seen from where she was standing. The push had been a reaction, not an attack. Zara felt her certainty shift. She had been so sure. She thought about all the times she had assumed she understood a situation from one angle. She told the teacher she was sorry she had jumped to conclusions, and the teacher said, ''It''s good that you wanted to tell someone, and even better that you listened to more of the story.'' Zara thought about that for the rest of the day.'),
        ('The Project That Fell Apart', 'Nadia''s group had a week to build a small model bridge for science class. For the first three days, they argued about who was in charge and whose idea to use. By Thursday, they had nothing built and one day left. Nadia felt it was time to act. She gathered everyone at the table and said, ''We have one day. Let''s pick the simplest idea and just build it.'' No one had a better plan, so they agreed. They worked through lunch and stayed-in for recess. The bridge they built wasn''t the best-looking one, but it held the weight. Nadia learned that sometimes saying the obvious thing out loud is leadership, even when no one officially asked you to lead.'),
        ('When Helping Hurts', 'Devon noticed his friend Ella struggling with a reading worksheet and immediately started reading the answers out loud to her. Ella''s face didn''t light up the way he expected; she looked a little surprised. ''I was trying to figure it out,'' she said. Devon felt confused. He thought he had been helpful. Later, Ella explained that she wanted to try things herself even when it was hard, and that being given the answer took away the feeling of getting there. Devon hadn''t thought about it that way. He had helped the way he would have wanted to be helped, but Ella had her own way of doing things. He asked her, ''What would actually be helpful?'' and she said, ''Just stay nearby.'' He sat with her the rest of the period without saying anything, and that turned out to be the right kind of help.'),
        ('The Compliment That Was Hard to Receive', 'When Mr. Okafor read Tomás''s story aloud to the class as an example of great writing, Tomás felt two things simultaneously: proud and a little uncertain. He didn''t know where to look. Some students turned to smile at him; others just kept their eyes on the teacher. At first Tomás wanted to say ''it wasn''t that good.'' But then he stopped himself. Why was it so hard to just say thank you? He thought it was because receiving a compliment felt like making a claim about yourself, like saying, yes, I agree I''m good at this. After class, Mr. Okafor asked if he was okay. Tomás said, ''It''s hard to let people say nice things about you.'' His teacher nodded. ''That''s something worth practicing,'' he said.'),
        ('Saying No When It Matters', 'A group of older students asked Nia to help them sneak candy from the classroom supply without the teacher noticing. They made it sound fun, like a small adventure with no real consequences. Nia felt the pull of wanting to belong to their group. But something in her stomach said no. She knew that feeling well; it had always guided her right. She told them she didn''t want to do it and walked away. Behind her, she heard someone say, ''Whatever.'' It stung a little. But when she sat back down at her desk, the feeling in her stomach had lifted, replaced by something steadier. She thought about how much more she trusted herself now than she had a year ago. That felt like something worth keeping.'),
        ('The Kid Who Was Always Loud', 'There was a student in the class named Remy who talked constantly, interrupted others, and seemed unable to sit still. Some students found him a lot to keep up with. Isabel did too, at first. But one day she noticed that Remy''s interruptions were usually because he had an idea he was afraid of losing. He wasn''t trying to take over; he was afraid the thought would disappear before he could say it. She also noticed that when a teacher gave him a small job to do, like handing out papers or timing the experiment, he focused completely and did it well. Isabel started seeing him differently. She didn''t suddenly find him easy to sit next to. But she stopped thinking he was doing it on purpose. That change in how she saw him made her a little more curious, and a little more patient.'),
        ('What the Argument Was Really About', 'Priya and her sister had been arguing all morning about whose turn it was to pick the TV show. By the time their mom separated them, neither one could remember how it had started. Their mom sat them both down and said, ''What is this actually about?'' Priya thought about it. She realized she was still upset from the day before, when her sister had taken her spot at the dinner table without asking. The TV argument wasn''t really about TV. Her sister admitted she was tired and had wanted control over something small after a hard week at school. They looked at each other. ''We were fighting about the wrong thing,'' Priya said. Her mom nodded. ''Most arguments are.'' They picked a show together and put on a blanket and didn''t talk for a while, and this time the quiet felt okay.'),
        ('Practicing in Front of the Mirror', 'Ahmad had to present his book report in front of the class, and he had three days to prepare. He was a quiet person, and the idea of standing at the front of the room made his voice go thin just thinking about it. The first time he practiced in front of his bedroom mirror, he stopped after ten seconds. His voice sounded strange. His hands didn''t know where to go. He made himself do it again, and again, and again, until the words came out in the right order without him having to think. On the day of the presentation, he still felt nervous. But he knew the words. And when his voice went thin at the beginning, he remembered his mirror and took a breath and found the words again. His teacher told him afterward, ''You seemed confident.'' He didn''t tell her that confidence had been something he had built, piece by piece, in a room by himself.'),
        ('When the Teacher Got It Wrong', 'The teacher marked one of Rosa''s answers wrong, but Rosa was sure she had calculated it correctly. She checked her work three times. She felt curious and a little uncertain: what if there was something she was missing? She raised her hand and said calmly, ''Could you help me understand why this is wrong? I checked it a few times and I''m getting the same answer.'' The teacher looked at the paper, then looked again. After a moment, she said, ''I think I made an error in the answer key. You''re right.'' The class went quiet. Rosa felt a warm mix of relief and care for her teacher. But the teacher said, ''Thanks for speaking up, Rosa; that''s how we all learn.'' Rosa thought about how much courage it had taken to say something, and how glad she was that she had.'),
        ('The Friend Who Changed', 'Zoe and her best friend Maya had done everything together since first grade. But this year, Maya had started spending more time with a new group and seemed different, quieter around Zoe and more confident around the others. Zoe felt something she didn''t have a name for at first. Eventually she found words for it: a kind of wistfulness, not like losing someone who moved away, but like missing a version of someone who was still right there. She tried talking to Maya about it, and Maya said, ''I''m still your friend. I''m just also becoming other things.'' Zoe thought about that for days. She realized she didn''t want to hold Maya to the version of her from second grade. As she allowed the friendship to change shape, she found that the new version still had room for her.'),
        ('The Compliment vs. the Flattery', 'A student named Finn had figured out that if he told Ms. Park her class was his favorite, she gave him more time on assignments. He kept doing it because it worked. But one day, a classmate named Bea said to him quietly, ''You don''t really mean it, do you?'' Finn paused, a little caught off guard, and wondered what the big deal was. Bea said, ''It''s not a compliment if it''s a strategy.'' Finn thought about that on the walk home. He decided she was right, even though he didn''t like it. He also thought about how he felt when someone said something kind to him that he wasn''t sure was real. The emptiness of that feeling was the same thing he had been giving Ms. Park. He stopped doing it. The next time he told her something good about the class, he made sure it was true.'),
        ('Waiting for the Right Moment', 'Simone had noticed for two weeks that her friend group kept using a nickname for another student, one the student hadn''t agreed to, and that Simone could see made her uncomfortable. Simone wanted to say something, but every time she started to, the moment passed. She told herself she was waiting for the right time. One afternoon, she realized there was no special moment coming; there was just the choice to say something or not. She said to the group, ''I think she doesn''t like being called that.'' The group went quiet. A few of them looked at each other. Then one of them said, ''I didn''t know it bothered her.'' The nickname stopped. Simone thought about all the times she had waited for the ''right moment'' and realized it was usually just fear with a better-sounding name.'),
        ('The Shortcut That Wasn''t', 'For a big reading project, Marcus found an article online that summarized the book instead of reading the whole thing. He used the summary to answer his questions and turned it in feeling like he had outsmarted the assignment. He got a good grade. But two weeks later, when the class discussed the book in detail, Marcus couldn''t keep up. Students were talking about scenes, characters, and moments he hadn''t read. He could follow the surface of the conversation but not the depth of it. He realized the grade hadn''t meant he had learned what the assignment was supposed to teach. He had traded understanding for a number, and the number couldn''t give him back what he had skipped. He decided not to do that again, not because he was afraid of getting caught, but because he wanted to be the kind of person who did the real work.'),
        ('When Two Friends Need You at the Same Time', 'At lunch on Tuesday, Elena''s friend Dani started crying about a fight she''d had with her parents. At the same time, Elena got a message that her friend Sasha had also had a hard morning and needed to talk. Elena couldn''t split herself in two. She stayed with Dani through lunch. Afterward, she found Sasha and explained. Sasha said, ''It''s fine,'' but her voice was flat. Elena felt the familiar pull of guilt, the sense that being there for one person meant she couldn''t be there for another. She talked to both of them that afternoon and then sat with it that night. She decided she couldn''t always be in two places at once, and that being fully present for one person was better than being half-present for two. She also decided to check in with Sasha first thing in the morning, not to fix it, just to show up.'),
        ('The Unspoken Rule', 'In Jonah''s class, there was an unwritten rule that you didn''t sit at the center table unless you had been in the class since the beginning of the year. Jonah had always followed it without questioning it; it was just how things were. When a new student named Petra sat at the center table on her second day, not knowing the rule, she was met with uncertain glances. Then, he remembered what it had felt like to walk into this classroom for the first time, three years ago. He made a choice: he picked up his tray, sat next to Petra, and started talking to her like it was the most ordinary thing. No one said anything. By the next week, two other students had done the same and more people felt welcome.'),
        ('The Trophy That Didn''t Feel Right', 'The school gave out a citizenship trophy to one student per grade at the end of each month. When Aisha won in November, she felt proud. The kind of proud that made her stand a little taller walking home. That night, she found herself thinking about three classmates whose kindness she had always admired: the quiet, steady kind that didn''t ask for attention. She wanted them to know someone had noticed even though they did not win. She wrote each of them a short note about something specific they had done and slipped them into their cubbies the next morning. Writing those notes had felt like her own kind of good.'),
        ('Carrying Someone Else''s Secret', 'Lena''s friend told her in confidence that she had been feeling left out of their friend group for months but hadn''t said anything because she was afraid of making it awkward. She asked Lena not to tell anyone. Lena agreed, and she carried the secret at every lunch and every group activity, watching her friend smile when the smile didn''t quite reach her eyes. Lena felt stuck. She couldn''t fix it without betraying the trust. She finally asked her friend, ''Is there anything I can do that doesn''t involve telling anyone?'' Her friend thought about it. ''Just sit next to me more,'' she said. So Lena did. It didn''t solve everything, but it changed something. Lena learned that sometimes keeping a secret well means finding what you can do inside the silence.'),
        ('The Good Reason That Still Hurt', 'Caleb''s teacher moved him away from his friend group because the four of them had been talking during lessons. The reason made sense to Caleb; the teacher was right. But understanding why something happened didn''t make the feeling of it disappear. He sat at his new seat and wondered about the fairness of being moved when his friends shared the same responsibility. He wondered if the others had been moved too. (They had.) He spent part of the morning angry, then part of it thinking about whether anger was still fair when the other person wasn''t wrong. He didn''t come to a clean answer. He decided that feelings didn''t have to be logical to be real, and that understanding someone''s reasoning and feeling upset about their decision could both be true at the same time.'),
        ('A Pattern She Hadn''t Seen', 'Elena had always thought of herself as patient. But when her teacher asked the class to reflect on a time they hadn''t listened, Elena thought back through the week. She had interrupted her partner twice during group work. She had finished her mom''s sentences three times. She had tuned out during the school meeting when the topic wasn''t about her grade. She hadn''t thought of any of those as impatience; they had just felt normal. But lined up together, they looked like a pattern. She wrote in her journal: ''I am patient when I want to be and impatient when I think my time matters more.'' She sat with that for a while. She didn''t know what to do with it yet. But she thought that seeing it clearly was probably the first step.'),
        ('Why He Never Raised His Hand', 'DeShawn was one of the smartest students in the class, and almost no one knew it, because he almost never raised his hand. He had done the math in his head once: the risk of being wrong in front of everyone felt bigger than the reward of being right. So he stayed quiet. One afternoon, the teacher asked a question no one could answer. The room was silent. DeShawn knew the answer. He felt it sitting in his chest. He waited to see if someone else would say it. No one did. He raised his hand slowly and gave the answer. The teacher said, ''That''s exactly right, DeShawn! And quite a sophisticated way to think about it.'' He realized that he did not suddenly become someone who always raised his hand. The next time he knew an answer, he felt confident to speak up in front of everyone.'),
        ('The Same Word, Different Meanings', 'During a class discussion about whether rules were fair, Marcus said that the school dress code was unfair. Another student, Priya, said it was completely fair. The two of them went back and forth for a few minutes before the teacher stopped them and asked, ''What does fair mean to each of you?'' Marcus said fair meant the same rules for everyone. Priya said fair meant rules that made sense for the situation. They looked at each other. They hadn''t been arguing about the dress code; they had been arguing from two different definitions of the same word. The teacher said, ''This is why definitions matter.'' Both of them started asking themselves about what they meant by each word before assuming what the other person meant.'),
        ('Being Good at Something You Hate', 'Olivia was a fast runner. Her gym teacher praised her every class, her friends assumed she loved track, and she had been automatically placed on the relay team. The thing was, she didn''t love running the way everyone assumed. She liked drawing; she had notebooks full of detailed illustrations that no one at school had ever seen. The running made her feel visible in a way she didn''t want. The drawing made her feel alive in a way she couldn''t explain. She finally told her gym teacher she didn''t want to be on the relay team. The teacher was surprised and asked why. Olivia said, ''Being good at something doesn''t mean I want to keep doing it.'' The teacher paused, then said that was fair and she''d figure something out. Olivia walked back to class thinking about all the ways people assume that talent equals love, when really the two are very different things.'),
        ('What Changes When You Watch Yourself', 'For a speaking project, students recorded themselves reading aloud and then had to watch the video. Most of the class laughed a little when they heard their own voices. Mia watched her recording twice. The first time, she noticed things to work on: her hair was a little messy, she stumbled over one word, she looked down too much. The second time, she tried to watch it the way she would watch someone else. She noticed that her voice was clear and her pacing was good and she actually looked confident even when she didn''t feel it. She thought about how different the two viewings were, even though they were the same video. She wondered how many times she had watched herself through the first lens and stopped there. She decided to start trying the second lens, not to excuse real mistakes, but to give herself the same credit she would give a friend.'),
        ('The Group She Would Have Missed', 'When the teacher assigned the end-of-year community project, Zara was placed in a group with two students she had never worked with and one she wasn''t sure about, a classmate named Finn who talked constantly and rarely seemed to listen. She approached the first meeting a little unsure of what to expect. But something unexpected happened in the second week: Finn, who had seemed scattered and loud in class, turned out to be genuinely creative under pressure, generating ideas faster than anyone Zara had worked with. He was still difficult to redirect once he got going. But she started to see the two things as separate: his noise and his talent were not the same thing, and dismissing one didn''t require dismissing the other. On the last day of the project, their group received the highest peer feedback score in the class. Zara thought about how close she had come to missing all of that. Instead she had learned something about the difference between a person who annoyed her and a person who was without value, and discovered, with some surprise, that she had been conflating the two.')
    ) AS v(lesson_name, new_value)
),
m1_passage_lc AS (
    UPDATE bantrly.lesson_content lc
    SET content_value = ud.new_value,
        updated_at = NOW()
    FROM bantrly.lesson l
    JOIN m1_passage_data ud ON ud.lesson_name = l.lesson_name
    WHERE lc.lesson_id = l.lesson_id
      AND lc.content_key = 'passage'
      AND l.difficulty_level = 'MEDIUM'
      AND l.created_by = 'ee42009d-d83e-4c12-abd1-2d8fff809b18'
      AND l.created_by_role = 'TEACHER'
    RETURNING l.lesson_name
),
m1_passage_lv AS (
    UPDATE bantrly.lesson_version_new lvn
    SET content = jsonb_set(
            lvn.content::jsonb,
            '{contents,0,content_value}',
            to_jsonb(ud.new_value)
        )
    FROM bantrly.lesson l
    JOIN m1_passage_data ud ON ud.lesson_name = l.lesson_name
    WHERE lvn.lesson_id = l.lesson_id
      AND lvn.is_latest = true
      AND l.difficulty_level = 'MEDIUM'
      AND l.created_by = 'ee42009d-d83e-4c12-abd1-2d8fff809b18'
      AND l.created_by_role = 'TEACHER'
    RETURNING lvn.title
)

SELECT
    (SELECT COUNT(*) FROM m1_passage_lc) AS m1_passage_content_updated,
    (SELECT COUNT(*) FROM m1_passage_lv) AS m1_passage_version_updated;

COMMIT;
